mapper.select:
SELECT e.id, e.exhibition_id AS exhibitionId, e.heritage_id AS heritageId, h.name AS heritageName, e.name, e.description, e.image, e.model_path AS modelPath, e.position_x AS positionX, e.position_y AS positionY, e.position_z AS positionZ, e.category, e.era, e.origin, e.material, e.history, e.craft, e.cultural_value AS culturalValue FROM t_exhibit e LEFT JOIN t_heritage h ON e.heritage_id = h.id WHERE e.deleted_flag = 0
AND e.exhibition_id = #{query.exhibitionId}
AND e.heritage_id = #{query.heritageId}
AND e.name LIKE CONCAT('%', #{query.keyword}, '%')
AND e.description LIKE CONCAT('%', #{query.description}, '%')
AND e.category = #{query.category}
ORDER BY e.sort ASC, e.id DESC
